/**
 * emit to subscription queries of type FindOrderItem,
 * but only if the id matches
 *
 * @param		entity	OrderItem
 */
	protected void emitFindOrderItem( OrderItem entity ) {
		LOGGER.info("handling emitFindOrderItem" );
		
	    queryUpdateEmitter.emit(FindOrderItemQuery.class,
	                            query -> query.getFilter().getOrderItemId().equals(entity.getOrderItemId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllOrderItem
	 * 
	 * @param		entity	OrderItem
	 */
	protected void emitFindAllOrderItem( OrderItem entity ) {
		LOGGER.info("handling emitFindAllOrderItem" );
		
	    queryUpdateEmitter.emit(FindAllOrderItemQuery.class,
	                            query -> true,
	                            entity);
	}

